418		for _, batch := range deleteUserBatches(contentIDs, deleteUserBatchSize) {
419			clause, args := deleteUserInClause(1, batch)
420			if _, err := tx.ExecContext(ctx, `DELETE FROM reaction WHERE content_id IN `+clause, args...); err != nil {
421				return err
422			}
423		}
