428		for _, batch := range deleteUserBatches(attachmentIDs, deleteUserBatchSize) {
429			clause, args := deleteUserInClause(1, batch)
430			if _, err := tx.ExecContext(ctx, `DELETE FROM attachment WHERE id IN `+clause, args...); err != nil {
431				return err
432			}
433		}
434		return nil
